from pathlib import Path
import json,html,re,textwrap,csv,io
R=Path(__file__).resolve().parents[3];C=json.loads((R/'assets/js/final-ten-configs.json').read_text());e=html.escape
source=(R/'tools/stock-coverage-planner/index.html').read_text();header=re.search(r'<header class="nav"[\s\S]*?</header>',source)[0];footer=re.search(r'<footer class="site"[\s\S]*?</footer>',source)[0]
controls=source[source.index('<section class="tool-panel tool-input"'):source.index('<section class="tool-panel no-print tool-guide"')]
saving=re.search(r'<h3 id="saving">[\s\S]*?<h3 id="questions">',source)[0].split('<h3 id="questions">')[0]
css=[]
def head(title,desc,url,img,application=False):
 schema={'@context':'https://schema.org','@type':'WebApplication' if application else 'WebPage','name':title,'url':url,'description':desc,'image':'https://nexalyplanner.com'+img}
 if application:schema.update(applicationCategory='BusinessApplication',operatingSystem='Web browser',isAccessibleForFree=True,offers={'@type':'Offer','price':'0','priceCurrency':'USD'})
 return f'''<!doctype html><html lang="en-US"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="index,follow"><title>{e(title)} | NexalyPlanner</title><meta name="description" content="{e(desc)}"><link rel="canonical" href="{url}"><meta property="og:title" content="{e(title)}"><meta property="og:description" content="{e(desc)}"><meta property="og:image" content="https://nexalyplanner.com{img}"><meta name="twitter:card" content="summary_large_image"><meta property="article:published_time" content="2026-10-21"><meta property="article:modified_time" content="2026-10-21"><link rel="stylesheet" href="/assets/css/style.css"><link rel="stylesheet" href="/assets/css/free-tools.css"><link rel="stylesheet" href="/assets/css/small-tools.css"><link rel="stylesheet" href="/assets/css/next-planner-ux.css"><link rel="stylesheet" href="/assets/css/oct16-planners.css"><link rel="stylesheet" href="/assets/css/final-ten.css"><script type="application/ld+json">{json.dumps(schema)}</script></head><body>'''+header
for idx,c in enumerate(C):
 slug=c['slug'];gslug=slug if slug.startswith('free-') else 'free-'+slug;name=c['name'];img='/assets/img/tools/'+slug+'-workflow.svg';url='https://nexalyplanner.com/tools/'+slug+'/';guideurl='https://nexalyplanner.com/guides/'+gslug+'/'
 titlelines=textwrap.wrap(name,30); title=''.join(f'<tspan x="70" dy="{0 if i==0 else 58}">{e(t)}</tspan>' for i,t in enumerate(titlelines))
 # Exact original worked-example diagram, not a product screenshot or AI photograph.
 svg=f'''<svg xmlns="http://www.w3.org/2000/svg" width="1200" height="800" viewBox="0 0 1200 800" role="img" aria-labelledby="title desc"><title id="title">{e(name)} worked example</title><desc id="desc">{e(' → '.join(c['visual']))}. Fictional planning example.</desc><rect width="1200" height="800" fill="#f6f2e9"/><rect width="24" height="800" fill="{c['color']}"/><circle cx="1080" cy="115" r="160" fill="{c['color']}" opacity=".12"/><text x="70" y="75" font-family="sans-serif" font-size="20" letter-spacing="3" fill="{c['color']}">NEXALYPLANNER / FREE WORKSHEET {idx+1:02}</text><text x="70" y="156" font-family="sans-serif" font-size="49" font-weight="700" fill="#203d4a">{title}</text>'''
 for i,label in enumerate(c['visual']):
  y=300+i*125;svg+=f'<rect x="70" y="{y}" width="1060" height="100" rx="18" fill="{c["color"] if i==2 else "#ffffff"}"/><circle cx="124" cy="{y+50}" r="25" fill="{("#ffffff" if i==2 else c["color"])}"/><text x="124" y="{y+58}" text-anchor="middle" fill="{c["color"] if i==2 else "#ffffff"}" font-family="sans-serif" font-size="24">{i+1}</text><text x="175" y="{y+61}" font-family="sans-serif" font-size="34" fill="{("#ffffff" if i==2 else "#203d4a")}">{e(label)}</text>'
 svg+='<text x="70" y="750" font-family="sans-serif" font-size="22" fill="#52616a">Fictional example · Review your inputs before acting</text></svg>'
 (R/img.lstrip('/')).write_text(svg)
 alt='Worked example: '+', then '.join(c['visual'])
 intro=f'''<nav aria-label="Breadcrumb"><a href="/">Home</a> / <a href="/tools/">Free planners</a> / {e(name)}</nav><div class="tool-intro"><p class="eyebrow">FREE · NO ACCOUNT NEEDED</p><h1>{e(name)}</h1><p>{e(c['description'])}</p><div class="tool-actions"><a class="tool-cta" href="#worksheet">Use free planner</a><a href="/guides/{gslug}/">Read full guide</a></div><p class="release-note">Published October 21, 2026 · Manual browser worksheet</p><figure class="oct16-cover"><img src="{img}" width="1200" height="800" alt="{e(alt)}" fetchpriority="high" decoding="async"><figcaption>Original diagram of the fictional worked example below.</figcaption></figure></div>'''
 summary=f'''<section class="tool-panel no-print tool-guide" id="tool-guide"><h2>How to use {e(name)}</h2><ol>{''.join('<li>'+e(s)+'</li>' for s in c['steps'])}</ol><h3>Calculation</h3><p>{e(c['formula'])}</p><h3>Try the fictional example</h3><p>{e(c['example'])}</p><h3>Limits</h3><p>{e(c['limits'])}</p>{saving}<p>CSV and PDF are reports. Use JSON for editable recovery. Device saves stay in this browser; clearing browser data can remove them.</p><p><a href="/guides/{gslug}/">Read the complete input guide and review workflow</a>.</p></section>'''
 page=head('Free '+name,c['description'],url,img,True)+f'<main class="free-tools new-tool next-tool theme-final-{idx}" data-tool="{slug}">'+intro+'<noscript><p>JavaScript is required for calculations and saving. Read the guide and worked example below without JavaScript.</p></noscript>'+controls+summary+'</main>'+''.join(f'<script src="/assets/js/{s}" defer></script>' for s in ['small-tools-models.js','final-ten-models.js','small-tools-ui.js','next-planner-ux.js','final-ten-ux.js'])+footer+'<div class="toast" id="toast" role="status"></div><script src="/assets/js/main.js" defer></script></body></html>'
 p=R/'tools'/slug/'index.html';p.parent.mkdir(exist_ok=True);p.write_text(page)
 fields=''
 for f in c['fields']+c['rowFields']:
  rule=('Optional. ' if f.get('optional') else 'Required. ')
  if f['type']=='number':rule+=('Whole numbers' if f['integer'] else 'Up to two decimals')+f' from {f["min"]} to {f["max"]}.'
  elif f['type']=='date':rule+='Calendar date, 1900–2200. Day differences include weekends.'
  elif f['type']=='select':rule+='Choose '+', '.join(f['options'])+'.'
  else:rule+='Up to 160 characters. Use a recognizable label without private account details.'
  fields+=f'<tr><th scope="row">{e(f["label"])}</th><td>{e(rule)}</td></tr>'
 rows=''.join(f'<li><a href="/tools/{s}/">{e(label)}</a></li>' for s,label in c['related'])
 sources=''
 if c['kind']=='calibration':sources='<p>Reference: <a href="https://www.nist.gov/calibrations/recommended-calibration-interval">NIST guidance on calibration intervals</a>. The planner deliberately uses your approved date rather than inventing a universal interval.</p>'
 guide=head(name+' Guide','Learn the inputs, calculation rules and fictional worked example for the '+name.lower()+'. Includes saving, backups and review steps.',guideurl,img)+f'''<main class="free-tools next-tool theme-final-{idx}"><nav aria-label="Breadcrumb"><a href="/tools/">Free planners</a> / <a href="/tools/{slug}/">{e(name)}</a> / Guide</nav><section class="tool-panel tool-guide"><p class="eyebrow">WORKSHEET GUIDE</p><h1>{e(name)}: inputs, example and review steps</h1><p>{e(c['description'])}</p><a class="tool-cta" href="/tools/{slug}/">Open the free worksheet</a><h2>Choose the scope first</h2><p>Use one review date and a clear worksheet label. Each row needs a unique record reference. The report describes only the entries in this worksheet; it cannot detect records you have left out. Use up to 100 rows per saved worksheet.</p><h2>Enter the records</h2><ol>{''.join('<li>'+e(s)+'</li>' for s in c['steps'])}</ol><div class="table-wrap" tabindex="0" role="region" aria-label="Input reference"><table><caption>Input rules</caption><thead><tr><th scope="col">Field</th><th scope="col">What to enter</th></tr></thead><tbody>{fields}</tbody></table></div><h2>Understand the calculation</h2><p>{e(c['formula'])}</p><h2>Worked example</h2><p>{e(c['example'])}</p><figure class="oct16-cover"><img src="{img}" width="1200" height="800" alt="{e(alt)}" loading="lazy" decoding="async"></figure><p>Open the worksheet and choose Load fictional example to reproduce the result. Change one input at a time and calculate again to see which assumption changes the output. Sample values are not recommended targets.</p><h2>Review and hand off</h2><p>{e(c['workflow'])}</p><p>Before sharing a report, check its label, review date, record identifiers and every exception. If the underlying event changes, update the inputs and calculate again. Keep the supporting receipt, order, inspection record or source reference outside this worksheet where appropriate.</p><h2>Save, recover and export</h2><p>Save on this device stores the editable worksheet in this browser. Restore reads that device save. Download backup creates a JSON file for another supported browser; Import backup previews the incoming records and asks before replacement. Import does not update the device save until you save again.</p><p>CSV exports the calculated report with settings and limitations. Print / Save PDF opens browser printing; choose Save as PDF if your browser offers it. These reports cannot restore editable data. Mobile print and download menus vary by device. There is no cloud sync, automatic alert or account recovery.</p><h2>Limits and common mistakes</h2><p>{e(c['limits'])}</p><p>A blank required field or duplicate reference should be corrected before calculation. Do not create a second master copy and edit both without reconciling them. Avoid putting passwords or sensitive account credentials into notes. The worksheet is a manual record, not an integration with the related business system.</p>{sources}<h2>Continue the workflow</h2><ul>{rows}<li><a href="/journal/{c['journal']}/">Related practical journal guide</a></li><li><a href="/tools/{slug}/">Return to this free planner</a></li></ul></section></main>'''+footer+'<script src="/assets/js/main.js" defer></script></body></html>'
 p=R/'guides'/gslug/'index.html';p.parent.mkdir(exist_ok=True);p.write_text(guide)
 css.append(f'.theme-final-{idx}'+'{--accent:'+c['color']+';--soft:#f4f3ec;--wash:#f4f3ec}')
# Scoped theme and accessible controls; shared layout stays intact.
(R/'assets/css/final-ten.css').write_text('\n'.join(css)+'\n.next-tool figcaption{font-size:.85rem;color:#52616a}.next-tool .tool-guide{overflow-wrap:anywhere}.next-tool .tool-guide h1{font-size:clamp(1.8rem,4vw,2.8rem)}.next-tool .tool-guide th{text-align:left}.next-tool .tool-cta{display:inline-block;padding:12px 18px;border-radius:10px}.next-tool .table-wrap:focus-visible{outline:3px solid var(--accent);outline-offset:3px}\n')
p=R/'tools/index.html';s=p.read_text()
for c in C:
 if f'href="/tools/{c["slug"]}/"' in s:continue
 card=f'''<article class="directory-tool theme-card" style="--accent:{c['color']}" data-category="{c['category']}" data-latest="true" data-search="{e(c['name']+' '+c['description'])}"><a class="directory-preview" href="/tools/{c['slug']}/" aria-label="Open {e(c['name'])}"><img src="/assets/img/tools/{c['slug']}-workflow.svg" width="1200" height="800" alt="{e(c['name'])} worked-example diagram" loading="lazy" decoding="async"></a><div class="library-card-body"><p class="library-card-meta"><span>Free planner</span><span class="library-new">Latest addition</span></p><h3><a href="/tools/{c['slug']}/">{e(c['name'])}</a></h3><p class="library-card-description">{e(c['description'])}</p><div class="library-card-footer"><a class="library-card-link" href="/tools/{c['slug']}/">Open free planner</a><span class="library-card-formats">CSV · JSON · Print</span></div></div></article>'''
 pat=r'(<section class="tool-category" id="'+c['category']+r'"[\s\S]*?<div class="library-grid">)';s,n=re.subn(pat,lambda m:m[1]+card,s,count=1);assert n==1
s=s.replace('40 free','50 free').replace('>40<','>50<');p.write_text(s)
p=R/'docs/fifty-planner-register.csv';rr=list(csv.DictReader(io.StringIO(p.read_text())));cols=list(rr[0]);routes={'/tools/'+c['slug']+'/':c for c in C}
for row in rr:
 if row['Route proposed'] in routes:row['Implementation status']='IMPLEMENTED 2026-10-21 - publication verification pending'
buf=io.StringIO();w=csv.DictWriter(buf,fieldnames=cols,lineterminator="\n");w.writeheader();w.writerows(rr);p.write_text(buf.getvalue())
print('Ten tools, ten guide pages, ten original diagrams and directory cards generated')
